def find_reachable_states(nfa, start_state, input_symbol):
    def dfs(current_state):
        reachable_states = {current_state}
        transitions = nfa.get(current_state, {}).get(input_symbol, set())
        for next_state in transitions:
            reachable_states.update(dfs(next_state))
        return reachable_states

    return dfs(start_state)

# Example usage
nfa = {
    'q0': {'a': {'q0', 'q1'}, 'b': {'q0'}},
    'q1': {'a': {'q1'}, 'b': {'q2'}},
    'q2': {'a': {'q2'}, 'b': {'q2'}}
}
start_state = 'q0'
input_symbol = 'a'
reachable_states = find_reachable_states(nfa, start_state, input_symbol)
print("Reachable states:", reachable_states)
